
/* ---------- effects, HUD ---------- */
function drawTrail(){
  if(!trail.length)return;
  var c=CH[chIdx],col=c.aura[Math.max(1,tier)];
  ctx.save();ctx.globalCompositeOperation='lighter';ctx.lineCap='round';ctx.lineJoin='round';
  for(var i=1;i<trail.length;i++){
    var a=trail[i-1],b=trail[i],k=1-b.age/26;if(k<=0)continue;
    ctx.strokeStyle=rgba(col,0.4*k);ctx.lineWidth=20*k+2;
    ctx.beginPath();ctx.moveTo(a.x,a.y-cam);ctx.lineTo(b.x,b.y-cam);ctx.stroke();
    ctx.strokeStyle='rgba(255,255,255,'+(0.45*k)+')';ctx.lineWidth=5*k;
    ctx.beginPath();ctx.moveTo(a.x,a.y-cam);ctx.lineTo(b.x,b.y-cam);ctx.stroke();
  }
  ctx.restore();
}
function drawTransFx(){
  if(!P||P.trans<=0)return;
  var k=P.trans/50,col=auraCol(state==='menu'?menuTier:tier),cx=P.x,cy=P.y-cam-38,i;
  ctx.save();ctx.globalCompositeOperation='lighter';
  var gr=ctx.createLinearGradient(0,0,0,cy);gr.addColorStop(0,rgba(col,0));gr.addColorStop(1,rgba(col,0.45*k));
  ctx.fillStyle=gr;ctx.fillRect(cx-22*k-4,0,(22*k+4)*2,cy);
  ctx.strokeStyle=rgba('#ffffff',0.6*k);ctx.lineCap='round';
  for(i=0;i<18;i++){
    var a=i/18*Math.PI*2+t*0.03,r0=40+(1-k)*60,r1=r0+40+(1-k)*110;
    ctx.lineWidth=2*k+0.5;ctx.beginPath();ctx.moveTo(cx+Math.cos(a)*r0,cy+Math.sin(a)*r0);ctx.lineTo(cx+Math.cos(a)*r1,cy+Math.sin(a)*r1);ctx.stroke();
  }
  ctx.restore();
}
function drawParts(){
  for(var i=0;i<parts.length;i++){
    var q=parts[i],k=q.life/q.max,sx=q.x,sy=q.y-cam;
    if(q.type==='paw'){var pa=k;ctx.save();ctx.globalAlpha=pa;ctx.globalCompositeOperation='lighter';glowDot(sx,sy,14,q.color,0.6);ctx.fillStyle='#e8ffb0';ctx.beginPath();ctx.ellipse(sx,sy+2,4,3.2,0,0,Math.PI*2);ctx.fill();[[-4.6,-2.6],[-1.6,-5.4],[1.6,-5.4],[4.6,-2.6]].forEach(function(o){ctx.beginPath();ctx.arc(sx+o[0],sy+o[1],1.6,0,Math.PI*2);ctx.fill();});ctx.restore();}
    else if(q.type==='leaf'){ctx.globalAlpha=Math.min(1,k*1.5);potLeaf(sx,sy,q.size,q.life*0.05,q.color);}
    else if(q.type==='dust'){ctx.globalAlpha=0.7*k;ctx.fillStyle=q.color;ctx.beginPath();ctx.arc(sx,sy,q.size*(1.6-k*0.6),0,Math.PI*2);ctx.fill();}
    else if(q.type==='spark'){
      ctx.globalAlpha=k;ctx.fillStyle=q.color;ctx.beginPath();
      ctx.moveTo(sx,sy-q.size*1.6);ctx.lineTo(sx+q.size*0.8,sy);ctx.lineTo(sx,sy+q.size*1.6);ctx.lineTo(sx-q.size*0.8,sy);ctx.closePath();ctx.fill();
    }else if(q.type==='ring'){
      ctx.globalAlpha=k;ctx.strokeStyle=q.color;ctx.lineWidth=Math.max(1,q.size*k*0.5);
      ctx.beginPath();ctx.arc(sx,sy,10+(1-k)*80,0,Math.PI*2);ctx.stroke();
    }
  }
  ctx.globalAlpha=1;
}
function drawPops(){
  for(var i=0;i<pops.length;i++){
    var o=pops[i],k=o.life/o.max,pop=1+0.35*Math.max(0,(k-0.8)/0.2);
    ctx.globalAlpha=Math.min(1,k*2.5);
    ctx.save();ctx.translate(clamp(o.x,80,W-80),o.y-cam);ctx.scale(pop,pop);
    outlineText(o.txt,0,0,o.size,o.color,'center');ctx.restore();
  }
  ctx.globalAlpha=1;
}
function glass(x,y,w,h,r,bord){
  ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-4,y);ctx.quadraticCurveTo(x+w,y,x+w,y+4);ctx.lineTo(x+w,y+h-r);ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);ctx.lineTo(x+4,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-4);ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();
  var g=ctx.createLinearGradient(0,y,0,y+h);g.addColorStop(0,'rgba(44,32,100,0.78)');g.addColorStop(1,'rgba(14,10,38,0.78)');
  ctx.fillStyle=g;ctx.fill();ctx.lineWidth=1.5;ctx.strokeStyle=bord||'rgba(255,213,61,0.55)';ctx.stroke();
}
function drawHUD(){
  var c=CH[chIdx],col=tier>0?c.aura[tier]:'#ffffff',i;
  glass(40,12,138,70,12);
  outlineText('FLOOR',54,34,15,'#ffe680','left');
  outlineText(String(floorsBest),54,72,38,'#ffffff','left');
  glass(W-178,12,138,70,12);
  outlineText('SCORE',W-54,34,15,'#ffe680','right');
  outlineText(fmt(score),W-54,72,30,'#ffffff','right');
  if(combo>0){
    glass(40,90,206,50,12,col);
    outlineText('COMBO x'+combo,54,118,26,col,'left');
    for(i=0;i<3;i++){ctx.beginPath();ctx.arc(200+i*15,104,5,0,Math.PI*2);ctx.fillStyle=tier>i?c.aura[i+1]:'rgba(255,255,255,0.18)';ctx.fill();ctx.lineWidth=1.2;ctx.strokeStyle=INK;ctx.stroke();}
    var k=clamp(comboT/COMBO_T,0,1);
    rr(54,126,178,7,3.5);ctx.fillStyle='rgba(255,255,255,0.16)';ctx.fill();
    if(k>0.03){rr(54,126,178*k,7,3.5);ctx.fillStyle=col;ctx.fill();}
  }
}
function drawPreview(pc,i,tr){
  var main=ctx,pctx=pc.getContext('2d');
  ctx=pctx;ctx.setTransform(1.5,0,0,1.5,0,0);ctx.clearRect(0,0,80,112);
  drawHero(40,104,PO,tr,i);
  ctx=main;
}
var PO=newHero();
function draw(){
  ctx.setTransform(cv.width/W,0,0,cv.height/H,0,0);
  ctx.clearRect(0,0,W,H);
  var sx=0,sy=0;if(shk>0&&SET.shake){sx=rnd(-3,3)*shk/22;sy=rnd(-3,3)*shk/22;}
  ctx.save();ctx.translate(sx,sy);
  drawBG();drawWalls();drawPlats();
  var tr=state==='menu'?menuTier:tier;
  drawTrail();
  drawTransFx();
  if(state==='play'||state==='wish')drawOrbs();
  drawWings();
  drawClone();drawFlyBack();
  if(fly&&fly.k==='tele'&&state==='play')drawTele();
  else if(state!=='over'){if(giantT>0&&state==='play'){var gsc=giantScale();ctx.save();ctx.translate(P.x,P.y-cam);ctx.scale(gsc,gsc);drawHero(0,0,P,tr,chIdx);ctx.restore();}else drawHero(P.x,P.y-cam,P,tr,chIdx);}
  drawFlyFront();
  if(state==='play'||state==='wish')drawBuddy();
  if(state==='play')drawAbilityFx();
  drawParts();drawPops();
  ctx.restore();
  if(state==='wish')drawWishFx();
  if(P&&P.trans>36&&state==='play'&&SET.shake){ctx.fillStyle='rgba(255,255,255,'+(0.3*(P.trans-36)/14)+')';ctx.fillRect(0,0,W,H);}
  if(state==='play'||state==='tpick'){drawHUD();syncSpecial();}
  if(state==='play'||state==='menu'){drawOrbRow();drawChips();}
  if(state==='menu'){for(var i=0;i<prev.length;i++)drawPreview(prev[i].cv,i,i===chIdx?menuTier:0);}
}

