/* ---------- pause and settings ---------- */
var pausedEl=document.getElementById('paused'),setEl=document.getElementById('settings'),pauseBtn=document.getElementById('pauseBtn'),gearBtn=document.getElementById('gearBtn'),setFrom='menu';
function syncTop(){
  pauseBtn.classList.toggle('hidden',state!=='play');var bs=document.getElementById('bS');if(bs)bs.classList.toggle('hidden',state!=='play');var bt=document.getElementById('bT');if(bt)bt.classList.toggle('hidden',state!=='play'||!isGod());
  gearBtn.classList.toggle('hidden',!(state==='menu'&&setEl.classList.contains('hidden')));
}
function pauseGame(){
  if(state!=='play')return;
  state='paused';keys.l=false;keys.r=false;jumpBuf=0;godHold=false;
  pausedEl.classList.remove('hidden');syncTop();
  var b=document.getElementById('resume');if(b)b.focus();
}
function resumeGame(){
  if(state!=='paused')return;
  pausedEl.classList.add('hidden');setEl.classList.add('hidden');
  state='play';last=0;acc=0;syncTop();
  if(document.activeElement&&document.activeElement.blur)document.activeElement.blur();
}
function openSettings(from){
  setFrom=from;syncSettings();
  setEl.classList.remove('hidden');
  if(from==='menu')menuEl.classList.add('hidden');else pausedEl.classList.add('hidden');
  syncTop();var b=document.getElementById('sSound');if(b)b.focus();
}
function closeSettings(){
  setEl.classList.add('hidden');
  if(setFrom==='menu'){menuEl.classList.remove('hidden');}else{pausedEl.classList.remove('hidden');}
  syncTop();
}
function syncSettings(){
  document.getElementById('sSound').setAttribute('aria-checked',muted?'false':'true');
  document.getElementById('sVol').value=SET.vol;
  document.getElementById('sMusic').setAttribute('aria-checked',SET.music!==false?'true':'false');
  document.getElementById('sVib').setAttribute('aria-checked',SET.vib?'true':'false');
  document.getElementById('sShake').setAttribute('aria-checked',SET.shake?'true':'false');
  document.getElementById('sLite').setAttribute('aria-checked',SET.lite?'true':'false');
  document.getElementById('sBig').setAttribute('aria-checked',SET.big?'true':'false');
  root.classList.toggle('big',!!SET.big);
}
function bindSw(id,fn){document.getElementById(id).addEventListener('click',function(){fn();saveSet();syncSettings();});}
bindSw('sSound',function(){toggleMute();});
bindSw('sMusic',function(){SET.music=SET.music===false;});
bindSw('sVib',function(){SET.vib=!SET.vib;vib(40);});
bindSw('sShake',function(){SET.shake=!SET.shake;});
bindSw('sLite',function(){SET.lite=!SET.lite;});
bindSw('sBig',function(){SET.big=!SET.big;root.classList.toggle('big',SET.big);resize();});
document.getElementById('sVol').addEventListener('input',function(e){SET.vol=parseInt(e.target.value,10)||0;saveSet();setVolNow();});
document.getElementById('sVol').addEventListener('change',function(){if(!muted){actx();sfx.combo(0);}});
pauseBtn.addEventListener('click',pauseGame);
gearBtn.addEventListener('click',function(){openSettings('menu');});
document.getElementById('resume').addEventListener('click',resumeGame);
document.getElementById('pSet').addEventListener('click',function(){openSettings('paused');});
document.getElementById('pHome').addEventListener('click',function(){pausedEl.classList.add('hidden');enterMenu();});
document.getElementById('sBack').addEventListener('click',closeSettings);
var scoresEl=document.getElementById('scores');
document.getElementById('allBtn').addEventListener('click',function(){renderBoard(document.getElementById('boardAll'),0,50);menuEl.classList.add('hidden');scoresEl.classList.remove('hidden');gearBtn.classList.add('hidden');});
