      ctx.stroke();ctx.strokeStyle='#6fd35a';ctx.lineWidth=1.6;ctx.stroke();
      ctx.fillStyle='#5fd35a';
      for(var yl=wrap(-cam,40)-40;yl<H+40;yl+=40){var lx=x0+dir*(6+Math.sin((yl+cam)*0.05)*3);ctx.beginPath();ctx.ellipse(lx+dir*4,yl,5,2.6,dir*0.6,0,Math.PI*2);ctx.fill();}
