  for(var i=0;i<10;i++)spawn('spark',P.x+rnd(-8,8),P.y-8,rnd(-1,1),rnd(0.5,2.5),rnd(14,24),rnd(2,3.5),col);
  spawn('ring',P.x,P.y-10,0,0,18,5,col);
