    f.t++;var sp=12*Math.min(1,f.t/30)*(f.t>f.dur-30?Math.max(0.3,(f.dur-f.t)/30):1);
    P.vy=-sp;P.y+=P.vy;P.vx+=(ax*6-P.vx)*0.2;P.x=clamp(P.x+P.vx,WALL+HW+10,W-WALL-HW-10);if(ax)P.dir=ax;P.on=false;P.flip=false;
