/* ---------- dragon art (made with Grok) ---------- */
var DRG={a:new Image(),b:new Image(),af:[[0, 0, 137, 215], [141, 0, 135, 218], [280, 0, 146, 194], [430, 0, 136, 216], [570, 0, 141, 128], [715, 0, 158, 112], [877, 0, 134, 202], [1015, 0, 83, 220]],bf:[[0, 0, 87, 150], [91, 0, 117, 148], [212, 0, 95, 139], [311, 0, 111, 138], [426, 0, 100, 140], [530, 0, 120, 95], [654, 0, 98, 140], [756, 0, 97, 141]],aok:false,bok:false,happy:0,dive:0};
DRG.a.onload=function(){DRG.aok=true;};DRG.b.onload=function(){DRG.bok=true;};
DRG.a.src='data:image/webp;base64,';DRG.b.src='data:image/webp;base64,';
function dpart(img,fr,x,y,ang,w,h,flip,trim){
  var sx=fr[0]+(trim||0),sw=fr[2]-2*(trim||0);
  ctx.save();ctx.translate(x,y);if(ang)ctx.rotate(ang);if(flip)ctx.scale(-1,1);
  ctx.drawImage(img,sx,fr[1],sw,fr[3],-w/2,-h/2,w,h);ctx.restore();
}
function dHead(k,x,y,hh,flip){var f=DRG.af[k];dpart(DRG.a,f,x,y,0,hh*f[2]/f[3],hh,flip);}
/* body made of repeating segments along a list of points (head first) */
function dBody(pts,rad,tailScale){
  var F=DRG.af,seg=F[4],tl=F[5],n=pts.length,i;
  // tail first (furthest back)
  var a=pts[n-1],b=pts[Math.max(0,n-4)],ang=Math.atan2(a.y-b.y,a.x-b.x),tr=rad(n-1)*tailScale;
  var tw=tr*2.6*tl[2]/tl[3],th=tr*2.6;
  dpart(DRG.a,tl,a.x+Math.cos(ang)*tw*0.35,a.y+Math.sin(ang)*tw*0.35,ang,tw,th,false,0);
  for(i=n-2;i>=1;i--){
    var p=pts[i+1],q=pts[i-1],an=Math.atan2(p.y-q.y,p.x-q.x),d=Math.sqrt((p.x-q.x)*(p.x-q.x)+(p.y-q.y)*(p.y-q.y))||1,r=rad(i);
    dpart(DRG.a,seg,pts[i].x,pts[i].y,an,Math.max(d*0.85,r*1.2),r*2.5,false,6);
  }
}
function drawDragonArt(headY,fade){
  var pts=dragonPts(headY),N=pts.length-1,i;
  ctx.save();ctx.globalCompositeOperation='lighter';glowDot(pts[0].x,pts[0].y,170,'#ffe27a',0.4*fade);ctx.restore();
  // claws behind the body
  [[9,6,1],[11,6,-1],[33,7,1],[35,7,-1]].forEach(function(c){
    var i0=c[0],p=pts[i0],q=pts[i0+1],dx=q.x-p.x,dy=q.y-p.y,m=Math.sqrt(dx*dx+dy*dy)||1,nx=-dy/m*c[2],ny=dx/m*c[2];
    var f=DRG.af[c[1]],hh=p.r*2.6,ww=hh*f[2]/f[3],ang=Math.atan2(ny,nx)-Math.PI/2+0.35*c[2];
    var sw=Math.sin(t*0.08+i0)*0.15;
    dpart(DRG.a,f,p.x+nx*(p.r*0.35+hh*0.42),p.y+ny*(p.r*0.35+hh*0.42),ang+sw,ww,hh,c[2]<0);
  });
  dBody(pts,function(k){return pts[k].r*1.05;},1.6);
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(i=2;i<=N;i+=6){var pu=0.55+0.45*Math.sin(t*0.12+i);glowDot(pts[i].x,pts[i].y,14,'#fff5be',0.5*pu*fade);}
  ctx.restore();
  var k=0;
  if(wishPhase===1)k=1;
  else if((wishPhase===2||wishPhase===4)&&wTyped<(wLines[wLine]||'').length)k=Math.floor(t/9)%2?3:0;
  else if(t%220<8)k=3;
  dHead(k,pts[0].x,pts[0].y-34,175,false);
}
function drawBuddyArt(){
  var f,face=buddy.leave?(buddy.x<W/2?-1:1):P.dir;
  if(buddy.leave)f=7;else if(DRG.dive>0)f=5;else if(DRG.happy>0)f=DRG.happy>30?6:4;else f=Math.floor(t/8)%4;
  if(DRG.happy>0)DRG.happy--;if(DRG.dive>0)DRG.dive--;
  ctx.save();ctx.globalCompositeOperation='lighter';glowDot(buddy.x,buddy.y-cam,40,'#ffe27a',0.3);ctx.restore();
  var fr=DRG.bf[f],hh=62*fr[3]/150;
  dpart(DRG.b,fr,buddy.x,buddy.y-cam+Math.sin(t*0.12)*2,0,hh*fr[2]/fr[3],hh,face<0);
}
function drawRideArt(){
  var h=fly.h,n=h.length;if(n<4)return;
  var pts=[],m=30,hx=P.x,hy=P.y-cam-112;for(var i=0;i<m;i++){var k=Math.min(1,i/6);pts.push({x:hx+Math.sin(t*0.13-i*0.42)*28*k,y:hy+i*13});}n=m;
  ctx.save();ctx.globalCompositeOperation='lighter';glowDot(P.x,P.y-cam+20,90,'#ffcf3a',0.3);ctx.restore();
  dBody(pts,function(k){return 24*(1-0.45*k/n);},1.4);
  fly.hx=pts[0].x;fly.hy=pts[0].y;
}


/* ---------- Beerus, the storm dragon (ride) ---------- */
var BEER={img:new Image(),m:{"w": 254, "h": 420, "n": 4, "gap": 4, "sx": 118, "sy": 132},ok:false};BEER.img.onload=function(){BEER.ok=true;};BEER.img.src='data:image/webp;base64,';
function drawBeerus(){
  var M=BEER.m,f=Math.floor(t/6)%4,sc=0.64,w=M.w*sc,h=M.h*sc,flip=P.dir>0;
  var k=Math.min(1,fly.t/30),off=(1-k)*(1-k)*420,end=fly.t>fly.dur-20?(fly.t-(fly.dur-20))/20:0;
  var sx=(flip?M.w-M.sx:M.sx)*sc,sy=M.sy*sc;
  var x=P.x-sx,y=P.y-cam-sy+off+Math.sin(t*0.2)*2;
  ctx.save();ctx.globalCompositeOperation='lighter';glowDot(P.x,P.y-cam+40,120,'#3fb8ff',0.35);ctx.restore();
  if(t%4===0)spawn('spark',x+rnd(20,w-20),y+rnd(h*0.3,h),rnd(-1,1),rnd(1,3),rnd(14,22),2.2,t%8?'#7cf3ff':'#ffffff');
  ctx.save();ctx.globalAlpha=1-end*0.6;ctx.translate(x,y);if(flip){ctx.translate(w,0);ctx.scale(-1,1);}
  ctx.drawImage(BEER.img,f*(M.w+M.gap),0,M.w,M.h,0,0,w,h);ctx.restore();
}

